import type { IndustryPack, PackOnboardingQuestion, ProductCapabilityRecommendation } from "../index.ts";

type CapabilityRow = readonly [featureKey: string, recommendation: ProductCapabilityRecommendation["recommendation"], rationale: string];

const recommendations = (...rows: readonly CapabilityRow[]): readonly ProductCapabilityRecommendation[] =>
  rows.map(([featureKey, recommendation, rationale]) => ({ featureKey, recommendation, rationale }));

const questions = (...items: readonly [key: string, prompt: string, answerType?: "boolean" | "number" | "enum", options?: readonly string[]][]): readonly PackOnboardingQuestion[] =>
  items.map(([key, prompt, answerType = "boolean", options]) => ({ key, prompt, answerType, ...(options ? { options } : {}) }));

const pack = (input: {
  key: string;
  displayName: string;
  customerTypes: readonly string[];
  terminology: IndustryPack["terminology"];
  locationFields: IndustryPack["locationFields"];
  asset: IndustryPack["assets"][number];
  services: IndustryPack["services"];
  recurrencePresets?: IndustryPack["recurrencePresets"];
  formSteps: IndustryPack["formSteps"];
  jobChecklist: IndustryPack["jobChecklist"];
  noncompletionReasons: IndustryPack["noncompletionReasons"];
  workflows: IndustryPack["workflows"];
  reports: IndustryPack["reports"];
  pricingTemplates: IndustryPack["pricingTemplates"];
  recommendationQuestions: IndustryPack["recommendationQuestions"];
  productCapabilityRecommendations: IndustryPack["productCapabilityRecommendations"];
  recommendedConnectorCapabilities: IndustryPack["recommendedConnectorCapabilities"];
  inventoryDefaults?: IndustryPack["inventoryDefaults"];
  website: IndustryPack["website"];
}): IndustryPack => {
  const triggerByFeature = {
    field_job_tracking: ["uses_field_technicians", "Do you send technicians to work at customer or fleet locations?"],
    route_planning: ["has_multiple_technicians", "Do you schedule multiple field technicians or several daily stops?"],
    inventory_tracking: ["stocks_parts", "Do you stock supplies or parts across a shop, van, or field crew?"],
    recurring_service_management: ["offers_recurring_service", "Do you offer recurring visits or customer-defined maintenance schedules?"],
    time_tracking: ["has_paid_staff", "Do you have paid staff whose work time you track?"],
    payroll_inputs: ["has_paid_staff", "Do you have paid staff whose hours or trip pay go to payroll?"],
    multi_location_management: ["operates_multiple_locations", "Do you operate more than one business location?"],
    advanced_reporting: ["needs_detailed_reporting", "Do you compare detailed results across teams, accounts, or services?"],
    online_booking: ["accepts_online_requests", "Do you accept customer service requests online?"],
  } as const;
  const recommendationQuestions = [...input.recommendationQuestions];
  const productCapabilityRecommendations = input.productCapabilityRecommendations.map((item) => {
    if (item.recommendation !== "conditional") return item;
    const trigger = triggerByFeature[item.featureKey as keyof typeof triggerByFeature];
    if (!trigger) throw new Error(`No onboarding trigger is configured for conditional capability ${item.featureKey} in ${input.key}`);
    if (!recommendationQuestions.some((question) => question.key === trigger[0])) {
      recommendationQuestions.push({ key: trigger[0], prompt: trigger[1], answerType: "boolean" });
    }
    return { ...item, rules: [{ when: { op: "equals" as const, answerKey: trigger[0], value: true }, recommendation: "normally_recommended" as const }] };
  });

  return {
    key: input.key,
    version: "1.0.0",
    displayName: input.displayName,
    customerTypes: input.customerTypes,
    terminology: input.terminology,
    locationFields: input.locationFields,
    assets: [input.asset],
    services: input.services,
    recurrencePresets: input.recurrencePresets ?? [{ key: "custom", label: "Set a customer or business schedule", custom: true }],
    formSteps: input.formSteps,
    jobChecklist: input.jobChecklist,
    noncompletionReasons: input.noncompletionReasons,
    workflows: input.workflows,
    defaultAutomations: [],
    reports: input.reports,
    pricingTemplates: input.pricingTemplates,
    recommendationQuestions,
    productCapabilityRecommendations,
    recommendedConnectorCapabilities: input.recommendedConnectorCapabilities,
    inventoryDefaults: input.inventoryDefaults ?? [],
    website: input.website,
  };
};

const standardWebsite = (headline: string, description: string, signupSteps: readonly string[], sections: readonly string[] = ["hero", "services", "how_it_works", "service_area", "faq", "reviews", "contact", "signup"]): IndustryPack["website"] => ({
  template: "fresh",
  sections,
  signupSteps,
  heroHeadline: headline,
  heroDescription: description,
});

